html:
{%- import "costeo_yelke/templates/print/oc_yelke.html" as oc -%}
{#- Encargo a taller (Subcontracting Order): el espejo de inventario de la orden de
    maquila -- qué se fabrica y qué materia prima se le manda al taller. Lo que se le
    entrega al taller es la Orden de Maquila; este es para control interno.
    Diseño: templates/print/oc_yelke.html -#}
{{ oc.estilos() }}
{{ oc.membrete_encabezado(doc, no_letterhead, print_settings, "Encargo a taller") }}
<div class="pdf-container">
{{ oc.marca_borrador(doc) }}
{{ oc.datos(doc, {"etiqueta": "Taller", "nombre": doc.supplier_name or doc.supplier, "rfc": rfc_tercero("Supplier", doc.supplier), "direccion": direccion_lineas(doc.get("supplier_address"))},
    [("Fecha de elaboración", fecha_corta(doc.transaction_date)),
     ("Entrega requerida", fecha_corta(doc.schedule_date) if doc.schedule_date else None),
     ("Orden de maquila", doc.purchase_order),
     ("Lote", doc.get("lote_ref")),
     ("Almacén del taller", doc.supplier_warehouse),
     ("Entrega en", doc.set_warehouse)]) }}
{{ oc.seccion("Lo que fabrica el taller") }}
<table class="items-table">
    <thead><tr>
        <th style="width:6mm">#</th><th>Producto</th>
        <th class="text-right" style="width:26mm">Cantidad</th>
        <th class="text-right" style="width:24mm">Costo unitario</th>
        <th class="text-right" style="width:27mm">Importe</th>
    </tr></thead>
    <tbody>
    {% for row in doc.items %}
        <tr>
            <td class="muted">{{ row.idx }}</td>
            <td>{{ oc.celda_articulo(row, con_descripcion=false) }}</td>
            <td class="num">{{ cantidad_uom(row.qty, row.stock_uom) }}</td>
            <td class="num">{{ row.get_formatted("rate", doc) }}</td>
            <td class="num"><b>{{ row.get_formatted("amount", doc) }}</b></td>
        </tr>
    {% endfor %}
    </tbody>
</table>
{{ oc.total_simple("Total", doc.get_formatted("total")) }}
{#- Tallas de ESTE lote (api/tallas_lote.tallas_de_encargo, método jinja de hooks.py).
    El encargo es el único documento que es de UN solo lote -- la orden de maquila
    cubre todos los lotes de ese taller --, así que es aquí donde el taller ve
    exactamente qué tallas le tocan en esta tanda y cuántas prendas son en total.
    Sin reparto por talla la sección no se dibuja y el documento queda como antes. -#}
{%- set por_producto = tallas_de_encargo(doc.name) -%}
{%- if por_producto %}
{{ oc.seccion("Tallas de este lote" ~ ((" · " ~ doc.get("lote_ref")) if doc.get("lote_ref") else "")) }}
<table class="items-table">
    <thead><tr>
        <th>Producto</th><th style="width:30mm">Género</th><th style="width:24mm">Talla</th>
        <th class="text-right" style="width:26mm">Cantidad</th>
    </tr></thead>
    <tbody>
    {%- for p in por_producto %}
        {%- for t in p.tallas %}
        <tr><td class="muted">{{ p.item_name or p.producto }}</td><td>{{ t.genero or "—" }}</td><td><b>{{ t.talla }}</b></td><td class="num">{{ "{:,.0f}".format(t.cantidad or 0) }}</td></tr>
        {%- endfor %}
        {%- if por_producto | length > 1 %}
        <tr><td colspan="3" class="text-right muted">Total {{ p.item_name or p.producto }}</td><td class="num"><b>{{ "{:,.0f}".format(p.total or 0) }}</b></td></tr>
        {%- endif %}
    {%- endfor %}
        <tr><td colspan="3" class="text-right"><b>Total de prendas terminadas</b></td><td class="num"><b>{{ "{:,.0f}".format(por_producto | sum(attribute="total")) }}</b></td></tr>
    </tbody>
</table>
{%- endif %}
{% if doc.supplied_items %}
{{ oc.seccion("Materia prima que se le envía") }}
<table class="items-table">
    <thead><tr>
        <th style="width:6mm">#</th><th>Material</th><th>Para</th>
        <th class="text-right" style="width:26mm">Requerido</th>
        <th class="text-right" style="width:26mm">Enviado</th>
    </tr></thead>
    <tbody>
    {% for rm in doc.supplied_items %}
        <tr>
            <td class="muted">{{ loop.index }}</td>
            <td><div class="item-title">{{ frappe.db.get_value("Item", rm.rm_item_code, "item_name") or rm.rm_item_code }}</div><div class="item-code"><span class="k">Código de producto:</span> {{ rm.rm_item_code }}</div></td>
            <td class="muted">{{ rm.main_item_code }}</td>
            <td class="num">{{ cantidad_uom(rm.required_qty, rm.stock_uom) }}</td>
            <td class="num">{{ cantidad_uom(rm.supplied_qty, rm.stock_uom) if rm.supplied_qty else "—" }}</td>
        </tr>
    {% endfor %}
    </tbody>
</table>
{% endif %}
{{ oc.cierre(doc, mostrar_pagos=false, mostrar_totales=false) }}
</div>
{{ oc.membrete_pie(doc, no_letterhead, print_settings) }}
